  "Add one for anything your school records that the standard form does not have, like a house or a bus pass number.": "अगर आपका स्कूल कुछ ऐसा दर्ज करता है जो सामान्य फ़ॉर्म में नहीं है, जैसे हाउस या बस पास नंबर, तो एक जोड़ें।",
