  "← Custom forms": "← कस्टम फ़ॉर्म",
  "This form is archived. Restore it to change it.": "यह फ़ॉर्म संग्रह में है। बदलने के लिए इसे वापस लाएँ।",
  "You have changes that are not published. People still fill in version": "आपके कुछ बदलाव जारी नहीं हुए हैं। लोग अब भी यह संस्करण भरते हैं:",
