  "Published": "जारी",
  ". Any change makes a draft until you publish again.": "। कोई भी बदलाव फिर से जारी करने तक एक मसौदा बनाता है।",
  "Add the first field, for example \"Teaching quality\" as a choice of Good, Average, Needs help.": "पहला खाना जोड़ें, जैसे \"पढ़ाई की गुणवत्ता\", अच्छा, ठीक-ठाक, मदद चाहिए के विकल्पों के साथ।",
  "← Forms & Approvals": "← फ़ॉर्म और स्वीकृतियाँ",
  "Each step names who approves, as a role or a named person, and up to which amount. A request goes to the first step whose limit covers it. Nobody ever approves their own request; it goes to the next approver. Changes apply to new requests.": "हर चरण बताता है कि कौन स्वीकार करता है, भूमिका या नामित व्यक्ति के रूप में, और किस राशि तक। अनुरोध उस पहले चरण पर जाता है जिसकी सीमा उसे शामिल करती है। कोई अपना अनुरोध खुद स्वीकार नहीं करता; वह अगले स्वीकारकर्ता के पास जाता है। बदलाव नए अनुरोधों पर लागू होते हैं।",
