  "Connect each channel to a provider. Keys are stored encrypted and never shown again. What each message says is in": "हर चैनल को किसी प्रदाता से जोड़ें। कुंजियाँ एन्क्रिप्ट करके रखी जाती हैं और फिर कभी नहीं दिखतीं। हर संदेश क्या कहता है, वह यहाँ है:",
