  "Test these details": "यह जानकारी जाँचें",
  "A new gateway starts switched off. Switch it on after a test passes.": "नया गेटवे बंद रहकर शुरू होता है। जाँच सफल होने के बाद इसे चालू करें।",
  "Add a gateway": "गेटवे जोड़ें",
  "Connect Razorpay and other gateways so parents can pay online. Which class or fee head uses which gateway is set in Fee Management, Fee Settings.": "Razorpay और दूसरे गेटवे जोड़ें ताकि अभिभावक ऑनलाइन भुगतान कर सकें। कौन-सी कक्षा या फ़ीस मद कौन-सा गेटवे इस्तेमाल करे, यह फ़ीस प्रबंधन, फ़ीस सेटिंग्स में तय होता है।",
  "Parents cannot pay online yet. Open a gateway, test it, then switch it on.": "अभिभावक अभी ऑनलाइन भुगतान नहीं कर सकते। कोई गेटवे खोलें, जाँचें, फिर चालू करें।",
