  "Inactive": "निष्क्रिय",
  "Test": "जाँच",
  "Not tested": "जाँचा नहीं गया",
  "Parents can pay at the counter in cash, UPI or cheque from day one. To take fees online, connect Razorpay (recommended) or another gateway.": "अभिभावक पहले दिन से काउंटर पर नकद, UPI या चेक से भुगतान कर सकते हैं। ऑनलाइन फ़ीस लेने के लिए Razorpay (सुझाया गया) या कोई दूसरा गेटवे जोड़ें।",
  "Test connection": "कनेक्शन जाँचें",
  "Switch on becomes available after a test passes.": "जाँच सफल होने के बाद चालू करने का विकल्प मिलता है।",
  "The gateway is switched off and hidden. Payments already made through it keep their record. You can restore it later.": "गेटवे बंद करके छिपा दिया जाता है। इससे पहले हुए भुगतानों का रिकॉर्ड रहता है। आप इसे बाद में वापस ला सकते हैं।",
  "Restore": "वापस लाएँ",
  "Add bank account": "बैंक खाता जोड़ें",
  "Online payments will no longer be split into": "ऑनलाइन भुगतान अब इसमें नहीं बँटेंगे:",
  ". Fee heads linked to it will need another account in Fee Settings. Payments already made keep their account.": "। इससे जुड़ी फ़ीस मदों को फ़ीस सेटिंग्स में दूसरा खाता चाहिए होगा। पहले हुए भुगतानों का खाता वही रहता है।",
  "It takes no payments. Payments already made through it keep their record.": "यह कोई भुगतान नहीं लेता। इससे पहले हुए भुगतानों का रिकॉर्ड रहता है।",
  "Payments through this gateway are pretend payments. Switch to live mode when Razorpay has activated your account.": "इस गेटवे से भुगतान नकली (टेस्ट) भुगतान हैं। Razorpay आपका खाता चालू कर दे तो लाइव मोड पर जाएँ।",
  "No bank account added. All online payments go to the main account linked to your Razorpay account.": "कोई बैंक खाता नहीं जोड़ा। सभी ऑनलाइन भुगतान आपके Razorpay खाते से जुड़े मुख्य खाते में जाते हैं।",
  "· account ending": "· खाता जिसके आख़िरी अंक",
