  "The main campus is the default for new records and documents.": "नए रिकॉर्ड और दस्तावेज़ों के लिए मुख्य कैंपस ही डिफ़ॉल्ट है।",
  "It drops out of campus choices. A campus that still has students, staff, academic years or logins cannot be archived. You can restore it later.": "यह कैंपस के विकल्पों से हट जाता है। जिस कैंपस में अब भी विद्यार्थी, स्टाफ़, शैक्षणिक वर्ष या लॉगिन हैं, उसे संग्रह में नहीं रखा जा सकता। आप इसे बाद में वापस ला सकते हैं।",
