  "Screens, receipts and certificates will show the school name without a logo. The file is kept and you can upload a logo again any time.": "स्क्रीन, रसीदें और प्रमाणपत्र बिना लोगो के स्कूल का नाम दिखाएँगे। फ़ाइल रखी जाती है और आप कभी भी फिर से लोगो अपलोड कर सकते हैं।",
  "The school can still change each of these in its module.": "स्कूल इनमें से हर एक को उसके मॉड्यूल में अब भी बदल सकता है।",
