  "You can see logins and roles here. The School Admin invites people and changes roles.": "आप यहाँ लॉगिन और भूमिकाएँ देख सकते हैं। लोगों को आमंत्रित करना और भूमिकाएँ बदलना स्कूल एडमिन का काम है।",
