  "disabled. Most staff get their login from": "बंद। ज़्यादातर स्टाफ़ को लॉगिन यहाँ से मिलता है:",
  "in Staff & HR. Everyone else is invited here.": "स्टाफ़ और HR में। बाकी सबको यहाँ आमंत्रित किया जाता है।",
  "Change the search or": "खोज बदलें या",
  "reset the filters": "फ़िल्टर रीसेट करें",
  "← Users & Permissions": "← यूज़र और अनुमतियाँ",
  "Lost the link? Make a new one; the old one stops working.": "लिंक खो गया? नया बनाएँ; पुराना काम करना बंद कर देता है।",
  "cannot open": "नहीं खोल सकते",
  ". Their records and history are kept.": "। उनके रिकॉर्ड और इतिहास रखे जाते हैं।",
  "This is you. Another School Admin must disable you or reset your two-step login.": "यह आप हैं। आपको बंद करना या आपका दो-चरण लॉगिन रीसेट करना किसी दूसरे स्कूल एडमिन को करना होगा।",
  "Linked to": "जुड़ा है:",
