  "Record type, action or record ID": "रिकॉर्ड का प्रकार, काम या रिकॉर्ड ID",
  "School OS (automatic)": "School OS (अपने-आप)",
  "No entries match these filters": "इन फ़िल्टरों से कोई प्रविष्टि मेल नहीं खाती",
  "No changes recorded yet": "अभी कोई बदलाव दर्ज नहीं",
  "Name of the new consent type": "नए सहमति प्रकार का नाम",
  "For example: Field trips, or Use of student work in the newsletter.": "जैसे: शैक्षिक भ्रमण, या न्यूज़लेटर में विद्यार्थी के काम का उपयोग।",
  "Title": "शीर्षक",
  "What guardians see as the heading.": "अभिभावक इसे शीर्षक के रूप में देखते हैं।",
  "Optional. Guardians who read this language see it; otherwise they see the first one.": "वैकल्पिक। इस भाषा में पढ़ने वाले अभिभावक इसे देखते हैं; बाकी पहली वाली देखते हैं।",
