  "Imports · Data Backup & Security": "आयात · डेटा बैकअप और सुरक्षा",
  "Import from a spreadsheet": "स्प्रेडशीट से आयात करें",
  "Upload, check the matched columns and every row, fix or leave out the rows with problems, then bring in the rest. Nothing is saved before that.": "अपलोड करें, मिलाए गए कॉलम और हर पंक्ति जाँचें, गड़बड़ वाली पंक्तियाँ ठीक करें या छोड़ दें, फिर बाकी ले आएँ। उससे पहले कुछ नहीं सहेजा जाता।",
  "Ready sheets": "तैयार शीटें",
  "Excel sheets made for your school, with drop-down lists of your own classes, designations and fee heads. Columns with a star must be filled.": "आपके स्कूल के लिए बनी Excel शीटें, आपकी अपनी कक्षाओं, पदों और फ़ीस मदों की ड्रॉप-डाउन सूचियों के साथ। तारे वाले कॉलम भरने ज़रूरी हैं।",
  "By": "द्वारा",
  "Result": "नतीजा",
  "Status": "स्थिति",
  "Nothing has been imported yet": "अभी कुछ आयात नहीं हुआ",
