  "Login history · Data Backup & Security": "लॉगिन इतिहास · डेटा बैकअप और सुरक्षा",
  "Search by IP address": "IP पते से खोजें",
  "Failed or locked": "असफल या लॉक",
  "Signed in or out": "साइन इन या आउट",
  "What happened": "क्या हुआ",
