  "Under the DPDP Act 2023, personal data is kept only as long as it is needed. Some records must be kept by law.": "DPDP अधिनियम 2023 के तहत निजी डेटा उतने ही समय रखा जाता है जितना ज़रूरी हो। कुछ रिकॉर्ड क़ानून के अनुसार रखने होते हैं।",
  "A person's data": "किसी व्यक्ति का डेटा",
  "When a parent, student or staff member asks to see or remove their data. Removal needs approval and is written to the audit log.": "जब कोई अभिभावक, विद्यार्थी या स्टाफ़ सदस्य अपना डेटा देखना या हटवाना चाहे। हटाने के लिए स्वीकृति चाहिए और यह ऑडिट लॉग में लिखा जाता है।",
