  "Worth a look": "देखने लायक",
  "Problems in red stop going live; the others do not.": "लाल वाली गड़बड़ियाँ गो लाइव रोकती हैं; बाकी नहीं।",
  "Everything matches.": "सब मेल खाता है।",
  "Fees due before go-live": "गो-लाइव से पहले की बकाया फ़ीस",
  "The fee plans cover the whole year. Months before the go-live date were the old software's, and are never billed twice.": "फ़ीस योजनाएँ पूरे साल की हैं। गो-लाइव तारीख़ से पहले के महीने पुराने सॉफ़्टवेयर के थे, और उनका कभी दो बार बिल नहीं बनता।",
  "What your old software says": "आपका पुराना सॉफ़्टवेयर क्या कहता है",
