  "Go live": "गो लाइव",
  "On going live, the move-in is marked done, and the go-live summary is kept. Records can still be added and imports undone.": "गो लाइव होने पर आने का काम पूरा माना जाता है, और गो-लाइव सारांश रखा जाता है। रिकॉर्ड फिर भी जोड़े जा सकते हैं और आयात पहले जैसे किए जा सकते हैं।",
  "Money brought in": "लाया गया पैसा",
  "Compare with the old software's balance and collection reports.": "पुराने सॉफ़्टवेयर की शेष और वसूली रिपोर्टों से मिलाएँ।",
