  "The first day School OS is your record. Any day of the year works. Fees due before it belong to the old software, and finance records start on it.": "वह पहला दिन जब School OS आपका रिकॉर्ड बनता है। साल का कोई भी दिन चलेगा। उससे पहले की बकाया फ़ीस पुराने सॉफ़्टवेयर की है, और वित्त रिकॉर्ड उसी दिन से शुरू होते हैं।",
  "Switching to School OS · Data Backup & Security": "School OS पर आना · डेटा बैकअप और सुरक्षा",
  "Set this year's fee structures": "इस साल के फ़ीस ढाँचे तय करें",
