  "Opening cash and bank balances": "शुरुआती नकद और बैंक शेष",
  "The Accountant enters the cash book and each bank account on the go-live date, and the financial year (April to March unless changed).": "लेखाकार गो-लाइव तारीख़ पर कैश बुक और हर बैंक खाता भरते हैं, और वित्तीय वर्ष (बदला न हो तो अप्रैल से मार्च)।",
  "Your school is moving in.": "आपका स्कूल School OS पर आ रहा है।",
  "Your move to School OS": "School OS पर आपका आना",
  "Bring in what your old software, Excel sheets or registers hold, in this order. You can start on any day of the year.": "आपके पुराने सॉफ़्टवेयर, Excel शीट या रजिस्टरों में जो है, उसे इसी क्रम में लाएँ। आप साल के किसी भी दिन शुरू कर सकते हैं।",
