  "Who approves each kind of request, up to which amount, and when it moves on if nobody decides. Changes apply to new requests.": "हर तरह के अनुरोध को कौन, किस राशि तक स्वीकार करता है, और कोई तय न करे तो वह कब आगे बढ़ता है। बदलाव नए अनुरोधों पर लागू होते हैं।",
  "They show at the end of the record's form and on its profile. Archiving a field keeps every answer already given.": "ये रिकॉर्ड के फ़ॉर्म के आख़िर में और उसकी प्रोफ़ाइल पर दिखते हैं। खाना संग्रह में रखने पर दिया गया हर जवाब रहता है।",
