  "A setting here replaces what the roles give for one module, wider or narrower, for this person only.": "यहाँ की सेटिंग किसी एक मॉड्यूल के लिए भूमिकाओं की दी हुई पहुँच को बदल देती है, ज़्यादा या कम, सिर्फ़ इस व्यक्ति के लिए।",
