  "Linking shows their classes, timetable and leave to them, and their login on their Staff Profile. One record only.": "जोड़ने से उन्हें उनकी कक्षाएँ, समय सारणी और छुट्टी दिखती है, और उनका लॉगिन उनकी स्टाफ़ प्रोफ़ाइल पर दिखता है। सिर्फ़ एक रिकॉर्ड।",
