  "The School Admin role must keep Full access to Settings, so someone can always manage logins and roles.": "स्कूल एडमिन भूमिका के पास सेटिंग्स की पूरी पहुँच रहनी चाहिए, ताकि कोई न कोई लॉगिन और भूमिकाएँ संभाल सके।",
  "This role was not found. It may have been archived.": "यह भूमिका नहीं मिली। हो सकता है संग्रह में रखी गई हो।",
