  "Only Transport, Library, Inventory and Hostel can be switched on or off. The other modules are always on.": "सिर्फ़ परिवहन, पुस्तकालय, भंडार और छात्रावास चालू या बंद हो सकते हैं। बाकी मॉड्यूल हमेशा चालू रहते हैं।",
  "Choose the first day of the week.": "सप्ताह का पहला दिन चुनें।",
  "Choose the roll number order.": "रोल नंबर का क्रम चुनें।",
  "Choose at least one role that may use the AI assistant.": "कम से कम एक भूमिका चुनें जो AI सहायक इस्तेमाल कर सके।",
  "This feature was not found.": "यह सुविधा नहीं मिली।",
  "Switch on the AI assistant first.": "पहले AI सहायक चालू करें।",
  "Choose a school-type template.": "स्कूल-प्रकार का टेम्पलेट चुनें।",
  "Details are complete.": "जानकारी पूरी है।",
  "Connect this integration first.": "पहले यह जुड़ाव जोड़ें।",
  "This person was not found in your school.": "यह व्यक्ति आपके स्कूल में नहीं मिला।",
  "Choose at least one role.": "कम से कम एक भूमिका चुनें।",
  "One of the chosen roles was not found. Reload the page and choose again.": "चुनी गई भूमिकाओं में से एक नहीं मिली। पेज फिर से लोड करके चुनें।",
  "Choose the campus.": "कैंपस चुनें।",
  "That campus was not found.": "वह कैंपस नहीं मिला।",
  "At least one School Admin must remain. Add another School Admin first.": "कम से कम एक स्कूल एडमिन रहना चाहिए। पहले दूसरा स्कूल एडमिन जोड़ें।",
  "That staff member was not found.": "वह स्टाफ़ सदस्य नहीं मिला।",
  "This person has already set a password, so they do not need an invite.": "यह व्यक्ति पासवर्ड बना चुका है, इसलिए आमंत्रण की ज़रूरत नहीं।",
  "This person is disabled in your school. Enable them first.": "यह व्यक्ति आपके स्कूल में बंद है। पहले चालू करें।",
  "At least one School Admin must remain with Settings. Add another School Admin first.": "सेटिंग्स के साथ कम से कम एक स्कूल एडमिन रहना चाहिए। पहले दूसरा स्कूल एडमिन जोड़ें।",
  "You cannot disable your own login. Ask another School Admin.": "आप अपना लॉगिन बंद नहीं कर सकते। किसी दूसरे स्कूल एडमिन से कहें।",
  "This person is already disabled.": "यह व्यक्ति पहले से बंद है।",
  "This person is already active.": "यह व्यक्ति पहले से सक्रिय है।",
  "The roles this person had are archived or switched off. Open the person and give them a role after enabling.": "इस व्यक्ति की भूमिकाएँ संग्रह में हैं या बंद हैं। चालू करने के बाद व्यक्ति को खोलकर कोई भूमिका दें।",
  "Only a School Admin or the Principal can reset two-step login.": "सिर्फ़ स्कूल एडमिन या प्रधानाचार्य दो-चरण लॉगिन रीसेट कर सकते हैं।",
  "You cannot reset your own two-step login. Ask another School Admin or the Principal.": "आप अपना दो-चरण लॉगिन रीसेट नहीं कर सकते। किसी दूसरे स्कूल एडमिन या प्रधानाचार्य से कहें।",
  "Choose the reason.": "कारण चुनें।",
  "Say how the person was confirmed, for example \"in person at the office\".": "बताएँ कि व्यक्ति की पुष्टि कैसे हुई, जैसे \"कार्यालय में मिलकर\"।",
  "Your two-step login was reset. You will set it up again at your next sign-in.": "आपका दो-चरण लॉगिन रीसेट हुआ। अगले साइन इन पर आप इसे फिर तैयार करेंगे।",
  "That student was not found.": "वह विद्यार्थी नहीं मिला।",
  "This login also works in another school, so only the person can change these details, in My profile.": "यह लॉगिन किसी दूसरे स्कूल में भी काम करता है, इसलिए ये जानकारी सिर्फ़ वही व्यक्ति मेरी प्रोफ़ाइल में बदल सकता है।",
  "The expiry date must be after the issue date.": "समाप्ति तारीख़ जारी करने की तारीख़ के बाद होनी चाहिए।",
  "Choose who can see it.": "चुनें कि कौन देख सकता है।",
  "One of the chosen roles was not found.": "चुनी गई भूमिकाओं में से एक नहीं मिली।",
  "Choose the document type.": "दस्तावेज़ का प्रकार चुनें।",
  "This document was not found.": "यह दस्तावेज़ नहीं मिला।",
