  "This kind of record is not known.": "इस तरह का रिकॉर्ड पहचाना नहीं गया।",
  "Choose between 1 month and 100 years, or keep for as long as the school uses School OS.": "1 महीने से 100 साल के बीच चुनें, या जब तक स्कूल School OS इस्तेमाल करे तब तक रखें।",
