  "This invite link has expired or was already used. Ask your School Admin for a new one.": "इस आमंत्रण लिंक की समय-सीमा ख़त्म हो गई या यह इस्तेमाल हो चुका है। अपने स्कूल एडमिन से नया माँगें।",
  "Choose a new password, not the temporary one your school gave you.": "नया पासवर्ड चुनें, स्कूल का दिया अस्थायी पासवर्ड नहीं।",
  "Send a new code first.": "पहले नया कोड भेजें।",
  "This code has been used or replaced. Send a new code.": "यह कोड इस्तेमाल हो चुका है या बदल गया है। नया कोड भेजें।",
  "This code has expired after 10 minutes. Send a new code.": "इस कोड का 10 मिनट का समय ख़त्म हो गया। नया कोड भेजें।",
  "Too many wrong codes. Send a new code.": "बहुत बार गलत कोड। नया कोड भेजें।",
  "This code has already been used. Send a new code.": "यह कोड पहले ही इस्तेमाल हो चुका है। नया कोड भेजें।",
  "1 hour": "1 घंटा",
  "4 hours": "4 घंटे",
  "Go to today": "आज पर जाएँ",
  "Attendance can be taken for today or earlier days.": "उपस्थिति आज या पिछले दिनों की ली जा सकती है।",
  "If the school opens that day, turn on \"allow attendance\" for the date in the School Calendar.": "अगर उस दिन स्कूल खुलता है, तो स्कूल कैलेंडर में उस तारीख़ के लिए \"उपस्थिति की अनुमति\" चालू करें।",
  "Holidays, Sundays and days off are left out of every %, report and register total.": "छुट्टियाँ, रविवार और अवकाश के दिन हर %, रिपोर्ट और रजिस्टर के जोड़ से बाहर रहते हैं।",
  "Open the register": "रजिस्टर खोलें",
  "Open Student Management": "विद्यार्थी प्रबंधन खोलें",
  "Students appear here once they are placed in this section in Student Management.": "विद्यार्थी प्रबंधन में इस सेक्शन में रखे जाने के बाद विद्यार्थी यहाँ दिखते हैं।",
  "A class not marked by": "जिस कक्षा की उपस्थिति इस समय तक नहीं ली गई:",
  "shows as not taken, and no absence message goes to parents. Remind sends the class teacher a message in the app.": "वह \"नहीं ली गई\" दिखती है, और अभिभावकों को अनुपस्थिति का संदेश नहीं जाता। \"याद दिलाएँ\" कक्षा शिक्षक को ऐप में संदेश भेजता है।",
  "Holidays and Sundays are never counted. Choose another date.": "छुट्टियाँ और रविवार कभी नहीं गिने जाते। दूसरी तारीख़ चुनें।",
  "Sections appear here once they have students.": "विद्यार्थी होने पर सेक्शन यहाँ दिखते हैं।",
  "students": "विद्यार्थी",
  "Green is 92% or more, amber 85% to 92%, red below 85%. Late counts as present; leave, holidays and Sundays are not counted.": "92% या ज़्यादा हरा, 85% से 92% पीला, 85% से कम लाल। देर से आना उपस्थित गिना जाता है; छुट्टी, अवकाश और रविवार नहीं गिने जाते।",
  "Now:": "अभी:",
  "Actions": "काम",
  "Showing": "दिखा रहे हैं",
  "to": "से",
  "The request is taken back from Approvals. Nothing in the register changes.": "अनुरोध स्वीकृतियों से वापस ले लिया जाता है। रजिस्टर में कुछ नहीं बदलता।",
  "This browser did not allow copying. Select the key and copy it by hand.": "इस ब्राउज़र ने कॉपी करने नहीं दिया। कुंजी चुनकर हाथ से कॉपी करें।",
  "I have copied it": "मैंने कॉपी कर ली",
  "More details: connection": "और जानकारी: कनेक्शन",
  "The old key stops working now. The device cannot send punches until you put the new key into it.": "पुरानी कुंजी अभी से काम करना बंद करती है। नई कुंजी डालने तक डिवाइस पंच नहीं भेज सकता।",
  "Find the person": "व्यक्ति ढूँढें",
  "Campus:": "कैंपस:",
