  "Check the point on a map": "नक्शे पर जगह जाँचें",
  "Device keys are shown only once, when the device is added or its key is regenerated.": "डिवाइस कुंजी सिर्फ़ एक बार दिखती है, जब डिवाइस जोड़ा जाता है या उसकी कुंजी फिर से बनती है।",
  "Print": "प्रिंट करें",
