  "Each day shows as Leave in Take Attendance, and no absence message goes to the parent for those days.": "उपस्थिति लें में हर दिन \"छुट्टी\" दिखता है, और उन दिनों अभिभावक को अनुपस्थिति का संदेश नहीं जाता।",
  "Send now": "अभी भेजें",
  ". Saved on this phone; it goes to school when the phone is online.": "। इस फ़ोन पर सहेजा गया; फ़ोन ऑनलाइन होते ही स्कूल पहुँचेगा।",
  "The marks for": "इसकी उपस्थिति:",
  "on": "को",
