  "It locked at": "यह लॉक हुई:",
  ". You may still take it; every change is recorded in the audit log.": "। आप अब भी ले सकते हैं; हर बदलाव ऑडिट लॉग में दर्ज होता है।",
  "You may still change it; every change is recorded in the audit log.": "आप अब भी बदल सकते हैं; हर बदलाव ऑडिट लॉग में दर्ज होता है।",
  "Tap only the students who are absent or late, then save.": "सिर्फ़ अनुपस्थित या देर से आए विद्यार्थियों पर टैप करें, फिर सहेजें।",
  "Save to keep them. You can change it until": "रखने के लिए सहेजें। आप इस समय तक बदल सकते हैं:",
  "Tap P, A or L for each student, or mark everyone present first.": "हर विद्यार्थी के लिए P, A या L टैप करें, या पहले सबको उपस्थित करें।",
