  "The key is shown once; keep it only in the device or its connector.": "कुंजी एक बार दिखती है; इसे सिर्फ़ डिवाइस या उसके कनेक्टर में रखें।",
  "Point the device, or its connector, at this address.": "डिवाइस, या उसके कनेक्टर, को इस पते पर लगाएँ।",
  "Send the key in the header": "कुंजी हेडर में भेजें",
  ". A GET to the same address checks the connection.": "। इसी पते पर GET से कनेक्शन जाँचा जाता है।",
  "Send punches in batches.": "पंच समूहों में भेजें।",
  "Up to 500 punches at a time, at most 60 requests a minute. Each punch needs the device's own unique punch number, so sending one twice counts once.": "एक बार में 500 तक पंच, एक मिनट में अधिकतम 60 अनुरोध। हर पंच को डिवाइस का अपना अलग पंच नंबर चाहिए, ताकि दो बार भेजा गया पंच एक बार गिना जाए।",
  "ZKTeco, eSSL and similar machines.": "ZKTeco, eSSL और ऐसी मशीनें।",
  "Set each person's user number on the machine to their staff ID or admission number; Auto-match then links them. Use the push or ADMS setting, or a small connector on a school computer. Keep the machine's clock right.": "मशीन पर हर व्यक्ति का यूज़र नंबर उनकी स्टाफ़ ID या प्रवेश संख्या रखें; फिर ऑटो-मिलान उन्हें जोड़ देता है। push या ADMS सेटिंग इस्तेमाल करें, या स्कूल के किसी कंप्यूटर पर छोटा कनेक्टर। मशीन की घड़ी सही रखें।",
  "All devices": "सभी डिवाइस",
  "Its punches are received but rejected until it is active again.": "इसके पंच मिलते हैं पर फिर से सक्रिय होने तक अस्वीकार होते हैं।",
