  "No sections are set up for this academic year yet. Add them in Academic Setup.": "इस शैक्षणिक वर्ष के लिए अभी कोई सेक्शन तैयार नहीं। उन्हें शैक्षणिक सेटअप में जोड़ें।",
  "Open Attendance Settings": "उपस्थिति सेटिंग्स खोलें",
