  "). You can still change it directly in": ")। आप इसे अब भी सीधे यहाँ बदल सकते हैं:",
  "There are no": "कोई नहीं:",
  "here.": "यहाँ।",
  "A correction does not send a new absence message to parents.": "सुधार से अभिभावकों को अनुपस्थिति का नया संदेश नहीं जाता।",
