  "Reason:": "कारण:",
  "This correction is waiting for the approver in Approvals.": "यह सुधार स्वीकृतियों में स्वीकार करने वाले की प्रतीक्षा में है।",
  "Changes asked for": "माँगे गए बदलाव",
  "The saved version and the second version side by side": "सहेजा गया संस्करण और दूसरा संस्करण साथ-साथ",
