  "Attendance reports are for teachers of a class, HR, the School Admin and the Principal.": "उपस्थिति रिपोर्ट कक्षा के शिक्षकों, HR, स्कूल एडमिन और प्रधानाचार्य के लिए हैं।",
  "Attendance is off for this date. Choose another date.": "इस तारीख़ के लिए उपस्थिति बंद है। दूसरी तारीख़ चुनें।",
