  "Nobody. Every change after the lock is a correction request.": "कोई नहीं। लॉक के बाद हर बदलाव एक सुधार अनुरोध है।",
  "Change the message": "संदेश बदलें",
  "The “Absent today” message is switched off in Communication, Message Settings.": "“आज अनुपस्थित” संदेश संचार, संदेश सेटिंग्स में बंद है।",
  "No channel that can carry it is switched on. Connect WhatsApp or SMS in Settings, Messaging.": "इसे ले जा सकने वाला कोई चैनल चालू नहीं है। सेटिंग्स, संदेश में WhatsApp या SMS जोड़ें।",
