  "Record overtime with a note when staff work extra hours.": "जब स्टाफ़ ज़्यादा घंटे काम करे तो नोट के साथ ओवरटाइम दर्ज करें।",
  "Add a shift, such as Morning 7:00 AM to 1:00 PM, then assign staff to it.": "एक शिफ़्ट जोड़ें, जैसे सुबह 7:00 AM से 1:00 PM, फिर उसमें स्टाफ़ रखें।",
