  "No parent can get this message: no phone number, or they opted out. Print the receipt instead.": "कोई अभिभावक यह संदेश नहीं पा सकता: फ़ोन नंबर नहीं, या उन्होंने मना किया। इसके बजाय रसीद छापें।",
