  "Type the go-live date on the go-live check first (Settings, Data Backup & Security, Switching to School OS).": "पहले शुरुआत जाँच पर शुरुआत की तारीख़ लिखें (सेटिंग्स, डेटा बैकअप और सुरक्षा, School OS पर आना)।",
