  "Use this when a phone is lost. The old link stops opening at once, and a new link is sent to +91": "फ़ोन खोने पर इसका इस्तेमाल करें। पुराना लिंक तुरंत खुलना बंद हो जाता है, और नया लिंक भेजा जाता है +91",
  "No documents for this parent. They are added on a child’s Documents tab.": "इन अभिभावक के कोई दस्तावेज़ नहीं। ये बच्चे के दस्तावेज़ टैब पर जोड़े जाते हैं।",
