  "Keep": "रखें",
  ") and move another record's children, consent records and documents to it. The other record is archived, not deleted.": ") और दूसरे रिकॉर्ड के बच्चे, सहमति रिकॉर्ड और दस्तावेज़ इसमें ले जाएँ। दूसरा रिकॉर्ड संग्रहित होता है, मिटाया नहीं जाता।",
  "Phone or name": "फ़ोन या नाम",
  "Each parent gets a request through Parent Link and agrees with a one-time code sent to their registered mobile. Staff never tick consent for a parent. Consents already given are left as they are.": "हर अभिभावक को पेरेंट लिंक से अनुरोध मिलता है और वे अपने दर्ज मोबाइल पर भेजे एक बार के कोड से सहमति देते हैं। स्टाफ़ कभी अभिभावक के लिए सहमति टिक नहीं करता। पहले दी गई सहमतियाँ जैसी हैं वैसी रहती हैं।",
  "Parents of a section": "एक सेक्शन के अभिभावक",
  "Choose section": "सेक्शन चुनें",
