  "No clearance checks run yet: fee dues and library books are checked here once Fee Management and Library Management are in use.": "अभी कोई क्लीयरेंस जाँच नहीं चली: फ़ीस प्रबंधन और पुस्तकालय प्रबंधन के इस्तेमाल में आने पर फ़ीस बकाया और पुस्तकालय की किताबें यहाँ जाँची जाती हैं।",
  "Student Profile": "विद्यार्थी प्रोफ़ाइल",
  ". Settle each one below, or ask for a waiver with a reason.": "। नीचे हर एक निपटाएँ, या कारण के साथ छूट माँगें।",
  "Nothing to check yet: fee dues and library books are checked here once Fee Management and Library Management are in use. Clearance passes.": "अभी जाँचने को कुछ नहीं: फ़ीस प्रबंधन और पुस्तकालय प्रबंधन के इस्तेमाल में आने पर फ़ीस बकाया और पुस्तकालय की किताबें यहाँ जाँची जाती हैं। क्लीयरेंस पास है।",
  "· checked": "· जाँचा गया",
  ". The waiver goes to Approvals; someone allowed to approve it decides. The check stays pending until then.": "। छूट स्वीकृतियों में जाती है; जिसे स्वीकार करने की अनुमति है वह तय करता है। तब तक जाँच प्रतीक्षा में रहती है।",
  "See in Approvals": "स्वीकृतियों में देखें",
  "Issue TC": "TC जारी करें",
  "The status changes to": "स्थिति बदलकर हो जाती है",
  "from": "से",
  ". The record stays, and the student no longer shows in class lists.": "। रिकॉर्ड बना रहता है, और विद्यार्थी अब कक्षा सूचियों में नहीं दिखता।",
  "The status changes by itself on": "स्थिति अपने आप बदलती है इस तारीख़ को:",
  "stays in the class. A TC that is waiting for approval is cancelled too.": "कक्षा में रहता है। स्वीकृति की प्रतीक्षा वाला TC भी रद्द होता है।",
  "Mentor": "मार्गदर्शक",
  "Job board": "नौकरी बोर्ड",
  "Graduated students become alumni here. Mark them from the card on this page.": "उत्तीर्ण विद्यार्थी यहाँ पूर्व विद्यार्थी बनते हैं। इस पेज के कार्ड से उन्हें चिह्नित करें।",
  "An alumni record is made for each, with the graduation year and the parent's phone. You can add their career and college later.": "हर एक का पूर्व विद्यार्थी रिकॉर्ड बनता है, उत्तीर्ण होने के साल और अभिभावक के फ़ोन के साथ। उनका करियर और कॉलेज बाद में जोड़ सकते हैं।",
  "recorded. Add one on an alumnus's record; the receipt is made in Finance, Income.": "दर्ज। किसी पूर्व विद्यार्थी के रिकॉर्ड पर एक जोड़ें; रसीद वित्त, आय में बनती है।",
  "Batch": "बैच",
  "donation": "दान",
  "· receipts through Finance, Income": "· रसीदें वित्त, आय से",
  "No donations recorded.": "कोई दान दर्ज नहीं।",
  "Record a donation": "दान दर्ज करें",
  "Not mentoring anyone yet. Link a student on the Alumni page.": "अभी किसी के मार्गदर्शक नहीं। पूर्व विद्यार्थी पेज पर किसी विद्यार्थी को जोड़ें।",
  "posted": "पोस्ट किया",
  "How to apply:": "आवेदन कैसे करें:",
  "The post is removed from the board and kept in the records.": "पोस्ट बोर्ड से हटती है और रिकॉर्ड में रहती है।",
  "Fee dues, library books and other items are checked first. The TC can be issued when every check is clear. The student's status changes on the last date.": "पहले फ़ीस बकाया, पुस्तकालय की किताबें और दूसरी चीज़ें जाँची जाती हैं। हर जाँच साफ़ होने पर TC जारी हो सकता है। विद्यार्थी की स्थिति आख़िरी तारीख़ पर बदलती है।",
  "For example the parent's letter. PDF or photo, up to 5 files of 10 MB.": "जैसे अभिभावक का पत्र। PDF या फ़ोटो, 10 MB की 5 फ़ाइलों तक।",
