  "Numbers": "नंबर",
  "Photo, identifiers, emergency contacts and the school's extra fields are added on the Student Profile after saving.": "फ़ोटो, पहचान संख्याएँ, आपातकालीन संपर्क और स्कूल के अतिरिक्त फ़ील्ड सहेजने के बाद विद्यार्थी प्रोफ़ाइल पर जोड़े जाते हैं।",
  "For students who did not come through Admission Management, for example when moving from your old software. Only the main details are needed now; the rest is filled on the profile.": "उन विद्यार्थियों के लिए जो प्रवेश प्रबंधन से नहीं आए, जैसे पुराने सॉफ़्टवेयर से आते समय। अभी सिर्फ़ मुख्य जानकारी चाहिए; बाकी प्रोफ़ाइल पर भरी जाती है।",
  "Open the academic year and add classes and sections in": "शैक्षणिक वर्ष खोलें और कक्षाएँ और सेक्शन जोड़ें यहाँ:",
  ", then come back.": ", फिर वापस आएँ।",
