  "Aadhaar is changed with the personal details. Identifier types are set in Student Settings.": "आधार निजी जानकारी के साथ बदलता है। पहचान संख्या के प्रकार विद्यार्थी सेटिंग्स में तय होते हैं।",
  "The school has no extra fields for students. They are added in": "स्कूल के पास विद्यार्थियों के लिए अतिरिक्त फ़ील्ड नहीं हैं। वे यहाँ जोड़े जाते हैं:",
  "Settings, Forms & Approvals": "सेटिंग्स, फ़ॉर्म और स्वीकृतियाँ",
  "Only the School Admin or Principal can change a restriction.": "सिर्फ़ स्कूल एडमिन या प्रधानाचार्य प्रतिबंध बदल सकते हैं।",
  "Open the year in Academic Management first.": "पहले शैक्षणिक प्रबंधन में साल खोलें।",
  "Add another section in Academic Management to move students between sections. To move class, use Promotion.": "विद्यार्थियों को सेक्शनों के बीच ले जाने के लिए शैक्षणिक प्रबंधन में एक और सेक्शन जोड़ें। कक्षा बदलने के लिए “अगली कक्षा में भेजना” इस्तेमाल करें।",
  "Now in": "अभी इसमें",
  ". The student gets the next free roll number in the new section; the old section stays in the history.": "। विद्यार्थी को नए सेक्शन में अगला खाली रोल नंबर मिलता है; पुराना सेक्शन इतिहास में रहता है।",
  "has no class in": "की कोई कक्षा नहीं है इसमें:",
  ", for example after re-admission. Choose the class and section.": ", जैसे दोबारा प्रवेश के बाद। कक्षा और सेक्शन चुनें।",
  "A re-admission request is waiting in": "दोबारा प्रवेश का अनुरोध प्रतीक्षा में है यहाँ:",
  ". The status changes when it is approved.": "। स्वीकृत होने पर स्थिति बदलती है।",
  "No change can be made here. Promotion is done on the Promotion page, and leaving on Leaving & Alumni.": "यहाँ कोई बदलाव नहीं हो सकता। अगली कक्षा में भेजना उसी पेज पर होता है, और स्कूल छोड़ना “स्कूल छोड़ना और पूर्व विद्यार्थी” पर।",
  "Only the allowed changes are offered. Promotion, transfer, withdrawal and graduation are done on their own pages.": "सिर्फ़ अनुमत बदलाव दिखाए जाते हैं। कक्षोन्नति, स्थानांतरण, नाम वापसी और उत्तीर्ण होना अपने अलग पेजों पर होते हैं।",
  "chosen": "चुने गए",
