  "Edit student": "विद्यार्थी बदलें",
  "Restricted. Stored encrypted and shown masked to others.": "प्रतिबंधित। एन्क्रिप्ट करके रखा जाता है और दूसरों को छिपाकर दिखाया जाता है।",
  "Keep the Aadhaar number on record when the box is empty": "बॉक्स खाली होने पर आधार नंबर रिकॉर्ड में रखें",
