  "RFID cards are switched off in Student Settings.": "विद्यार्थी सेटिंग्स में RFID कार्ड बंद हैं।",
  "The RFID number has 4 to 32 letters A to F and digits, as printed on the card.": "RFID नंबर में A से F अक्षर और अंक, 4 से 32 तक होते हैं, जैसा कार्ड पर छपा है।",
  "This RFID card is already given to another student.": "यह RFID कार्ड पहले से दूसरे विद्यार्थी को दिया गया है।",
  "Type the RFID number. To give the student a new card, type the new number.": "RFID नंबर लिखें। विद्यार्थी को नया कार्ड देने के लिए नया नंबर लिखें।",
