  "RFID number saved.": "RFID नंबर सहेजा गया।",
  "This link was not found.": "यह लिंक नहीं मिला।",
  "This parent was not found.": "ये अभिभावक नहीं मिले।",
  "This parent was not found, or is not a parent of your students.": "ये अभिभावक नहीं मिले, या आपके विद्यार्थियों के अभिभावक नहीं हैं।",
  "Choose a photo (JPG or PNG).": "फ़ोटो चुनें (JPG या PNG)।",
