  "Give a reason of at least 5 characters for changing the restriction.": "प्रतिबंध बदलने के लिए कम से कम 5 अक्षरों का कारण दें।",
  "Link settings saved.": "लिंक सेटिंग्स सहेजी गईं।",
  "Only the School Admin or Principal can set a custody or access restriction.": "सिर्फ़ स्कूल एडमिन या प्रधानाचार्य अभिरक्षा या पहुँच प्रतिबंध लगा सकते हैं।",
  "Write the restriction note.": "प्रतिबंध का नोट लिखें।",
