  "Waiver asked. It is waiting in Approvals for someone allowed to approve it.": "छूट माँगी गई। यह स्वीकृतियों में स्वीकृति की अनुमति वाले व्यक्ति की प्रतीक्षा में है।",
  "Marked as left. The record stays in the Left list.": "छोड़ा हुआ चिह्नित। रिकॉर्ड “छोड़ चुके” सूची में रहता है।",
  "Leaving cancelled. The student stays in the class.": "स्कूल छोड़ना रद्द। विद्यार्थी कक्षा में रहता है।",
