  "Choose the type.": "प्रकार चुनें।",
  "Write what happened, in a few words.": "क्या हुआ, कुछ शब्दों में लिखें।",
  "The date cannot be in the future.": "तारीख़ आगे की नहीं हो सकती।",
  "A suspension needs a from date and a to date.": "निलंबन के लिए शुरुआती और अंतिम तारीख़ चाहिए।",
