  "Say who approved the suspension.": "बताएँ कि निलंबन किसने स्वीकृत किया।",
  "No academic year is open. Open one in Academic Management.": "कोई शैक्षणिक वर्ष खुला नहीं है। शैक्षणिक प्रबंधन में एक खोलें।",
  "This record was already archived.": "यह रिकॉर्ड पहले ही संग्रहित है।",
  "Behaviour points are switched off (Student Settings, Behaviour).": "व्यवहार अंक बंद हैं (विद्यार्थी सेटिंग्स, व्यवहार)।",
