  "Give a reason.": "कारण दें।",
  "Counselling is switched off (Student Settings, Behaviour).": "परामर्श बंद है (विद्यार्थी सेटिंग्स, व्यवहार)।",
  "Say why, in at least 5 characters.": "कम से कम 5 अक्षरों में क्यों, बताएँ।",
  "This student already has an open counselling case. Add a session to it instead.": "इस विद्यार्थी का परामर्श मामला पहले से खुला है। इसके बजाय उसमें सत्र जोड़ें।",
  "This case is closed. Reopen it to add a session.": "यह मामला बंद है। सत्र जोड़ने के लिए इसे फिर से खोलें।",
  "Write what was done in the session.": "सत्र में क्या किया गया, लिखें।",
  "Only the Counsellor can write confidential notes.": "सिर्फ़ परामर्शदाता गोपनीय नोट लिख सकते हैं।",
  "Career guidance is switched off (Student Settings, Behaviour).": "करियर मार्गदर्शन बंद है (विद्यार्थी सेटिंग्स, व्यवहार)।",
  "Give a title.": "शीर्षक दें।",
  "This bulk update was not found.": "यह सामूहिक बदलाव नहीं मिला।",
  "This bulk update was already undone.": "यह सामूहिक बदलाव पहले ही पूर्ववत हो चुका है।",
  "A TC is given only to a student who is leaving. Start leaving on Leaving & Alumni first.": "TC सिर्फ़ स्कूल छोड़ रहे विद्यार्थी को दिया जाता है। पहले “स्कूल छोड़ना और पूर्व विद्यार्थी” पर स्कूल छोड़ना शुरू करें।",
  "Migration certificates are switched off (Student Settings, Certificates).": "माइग्रेशन प्रमाणपत्र बंद हैं (विद्यार्थी सेटिंग्स, प्रमाणपत्र)।",
  "Write the purpose, for example \"bank account opening\".": "उद्देश्य लिखें, जैसे \"बैंक खाता खोलना\"।",
  "Choose the signatory.": "हस्ताक्षरकर्ता चुनें।",
  "A conduct or character certificate is signed by an authorised signatory. Choose one.": "आचरण या चरित्र प्रमाणपत्र पर अधिकृत हस्ताक्षरकर्ता हस्ताक्षर करते हैं। एक चुनें।",
  "A TC for this student is already waiting for approval.": "इस विद्यार्थी का TC पहले से स्वीकृति की प्रतीक्षा में है।",
  "Give a reason of at least 5 characters.": "कम से कम 5 अक्षरों का कारण दें।",
  "This certificate is already cancelled.": "यह प्रमाणपत्र पहले ही रद्द है।",
  "Consent is given only by the guardian, in Parent Link or on the admission form.": "सहमति सिर्फ़ अभिभावक देते हैं, पेरेंट लिंक में या प्रवेश फ़ॉर्म पर।",
  "This consent text was not found.": "यह सहमति लेख नहीं मिला।",
  "Say how the guardian asked, in at least 5 characters (for example \"Letter dated 12-10-2026\").": "कम से कम 5 अक्षरों में बताएँ कि अभिभावक ने कैसे कहा (जैसे \"12-10-2026 का पत्र\")।",
  "There is no consent of this type to withdraw.": "वापस लेने के लिए इस प्रकार की कोई सहमति नहीं है।",
